[{"order":1,"type":"heading","text":"Crash Reporting and Monitoring in React Native: Sentry, Firebase Crashlytics, and Performance APMs"},{"order":2,"type":"paragraph","text":"Building resilient React Native applications requires robust error tracking and performance monitoring. When production crashes happen, relying solely on user feedback is inefficient. This tutorial explores implementing industry-standard monitoring tools: Sentry, Firebase Crashlytics, and Application Performance Monitoring (APM) solutions."},{"order":3,"type":"heading","text":"1. Setting up Sentry for React Native"},{"order":4,"type":"paragraph","text":"Sentry provides deep stack traces, source map support, and real-time alerts for both JavaScript and native crashes. To begin, install the official Sentry React Native SDK via npm or yarn."},{"order":5,"type":"code","text":"npm install @sentry/react-native
npx @sentry/wizard -s -i reactNative"},{"order":6,"type":"paragraph","text":"The Sentry wizard automatically configures your android/ and ios/ directories, updates your build scripts to upload source maps, and injects the initialization code into your entry file."},{"order":7,"type":"subheading","text":"Initializing Sentry and Capturing Errors"},{"order":8,"type":"code","text":"import * as Sentry from '@sentry/react-native';

Sentry.init({
  dsn: 'YOUR_SENTRY_DSN_HERE',
  tracesSampleRate: 1.0,
});

// Manually capture an exception
try {
  // risky code
} catch (error) {
  Sentry.captureException(error);
}"},{"order":9,"type":"heading","text":"2. Integrating Firebase Crashlytics"},{"order":10,"type":"paragraph","text":"Firebase Crashlytics is a lightweight, real-time crash reporter that prioritizes and groups your crash data. For React Native, use the `@react-native-firebase/app` and `@react-native-firebase/crashlytics` modules."},{"order":11,"type":"code","text":"npm install @react-native-firebase/app @react-native-firebase/crashlytics"},{"order":12,"type":"subheading","text":"Recording Custom Crashlytics Logs"},{"order":13,"type":"paragraph","text":"You can record logs, set user identifiers, and force test crashes to verify your Crashlytics integration."},{"order":14,"type":"code","text":"import crashlytics from '@react-native-firebase/crashlytics';

async function handleUserAction() {
  await crashlytics().setUserId('user_12345');
  crashlytics().log('User triggered checkout flow');
}

// Force a test crash (uncomment only to test)
// crashlytics().crash();"},{"order":15,"type":"heading","text":"3. Implementing Performance APMs"},{"order":16,"type":"paragraph","text":"Application Performance Monitoring (APM) tracks network requests, slow screen renders, and custom traces. Both Sentry and Firebase Performance Monitoring offer APM tools for React Native."},{"order":17,"type":"subheading","text":"Using Firebase Performance Traces"},{"order":18,"type":"code","text":"import perf from '@react-native-firebase/perf';

async function fetchData() {
  const tracker = await perf().startTrace('custom_fetch_data_trace');
  try {
    const response = await fetch('https://api.example.com/data');
    await tracker.stop();
    return response.json();
  } catch (error) {
    await tracker.stop();
    throw error;
  }
}"},{"order":19,"type":"heading","text":"Best Practices for Mobile Monitoring"},{"order":20,"type":"bullet_point","text":"Always upload source maps during your CI/CD build process for Sentry to un-minify production stack traces."},{"order":21,"type":"bullet_point","text":"Sanitize user data before attaching it to crash reports to comply with GDPR and privacy regulations."},{"order":22,"type":"bullet_point","text":"Use breadcrumbs effectively to track the user journey leading up to an exception."},{"order":23,"type":"bullet_point","text":"Set sample rates for performance monitoring to avoid hitting network and battery quotas on user devices."}]
